#include <iostream>

class Account {
public:
    Account(double balance) : balance{balance} {}

    void setBalance(double balance) {
        // The parameter 'balance' hides the member 'balance'.
        // Account::balance resolves the hidden class member.
        Account::balance = balance;
    }

    double getBalance() const {
        return balance;
    }

private:
    double balance;
};

int main() {
    Account account{100.0};
    Account& accountRef = account;   // reference handle
    Account* accountPtr = &account;  // pointer handle

    std::cout << "Initial balance: " << account.getBalance() << "\n";

    // Accessing public member via reference handle using dot (.)
    accountRef.setBalance(250.50);
    std::cout << "Via reference:   " << accountRef.getBalance() << "\n";

    // Accessing public member via pointer handle using arrow (->)
    accountPtr->setBalance(500.75);
    std::cout << "Via pointer:     " << accountPtr->getBalance() << "\n";

    return 0;
}

#include <iostream>
#include <iomanip>
#include <stdexcept>

class Time {
public:
    // Constructor with default arguments acting as default constructor
    explicit Time(int hr = 0, int min = 0, int sec = 0) {
        setTime(hr, min, sec);
    }

    void setTime(int h, int m, int s) {
        setHour(h);
        setMinute(m);
        setSecond(s);
    }

    void setHour(int h) {
        if (h >= 0 && h < 24) hour = h;
        else throw std::invalid_argument("hour must be 0-23");
    }

    void setMinute(int m) {
        if (m >= 0 && m < 60) minute = m;
        else throw std::invalid_argument("minute must be 0-59");
    }

    void setSecond(int s) {
        if (s >= 0 && s < 60) second = s;
        else throw std::invalid_argument("second must be 0-59");
    }

    // Access functions (inspectors and predicates)
    unsigned int getHour() const { return hour; }
    unsigned int getMinute() const { return minute; }
    unsigned int getSecond() const { return second; }
    bool isAM() const { return hour < 12; }

    void printUniversal() const {
        std::cout << std::setfill('0') << std::setw(2) << hour << ":"
                  << std::setw(2) << minute << ":"
                  << std::setw(2) << second;
    }

private:
    unsigned int hour{0};
    unsigned int minute{0};
    unsigned int second{0};
};

int main() {
    Time t1;             // all arguments defaulted (00:00:00)
    Time t2(2);          // hour specified (02:00:00)
    Time t3(21, 34);     // hour, minute specified (21:34:00)
    Time t4(12, 25, 42); // all specified (12:25:42)

    t1.printUniversal(); std::cout << (t1.isAM() ? " AM" : " PM") << "\n";
    t2.printUniversal(); std::cout << (t2.isAM() ? " AM" : " PM") << "\n";
    t3.printUniversal(); std::cout << (t3.isAM() ? " AM" : " PM") << "\n";
    t4.printUniversal(); std::cout << (t4.isAM() ? " AM" : " PM") << "\n";

    try {
        Time t5(27, 74, 99); // bad values
    } catch (const std::invalid_argument& e) {
        std::cout << "Caught exception: " << e.what() << "\n";
    }

    return 0;
}
